/* 超维武仙：大旻长夜 · 玄铁朱墙（日里版）
   原卡 builtInCss 的作品组件层（§A—§O、§Q），风月平台壳层（§0—§13）和建档页留白（§P）不用；@supports 拆了壳，日里会把整段 @supports 丢掉。 */
/* ===== 第二层：作品组件层 ===== */
/* ===== §A 主容器与基础排版 ===== */
.cw-runtime{
--cw-bg:#080b10!important;
--cw-bg-soft:#0d1219!important;
--cw-panel:#121821!important;
--cw-panel-raised:#171e29!important;
--cw-panel-high:#1c2531!important;
--cw-ink:#ece4d4!important;
--cw-sub:#b9ae99!important;
--cw-muted:#827968!important;
--cw-gold:#d2ad62!important;
--cw-gold-soft:#8d703a!important;
--cw-red:#b95e5a!important;
--cw-blue:#6c99b8!important;
--cw-green:#6f9f7b!important;
--cw-purple:#917bb1!important;
--cw-cyan:#5f9d9c!important;
--cw-bronze:#aa7448!important;
--cw-line:rgba(207,171,96,.25)!important;
--cw-radius:14px!important;
width:min(100%,980px)!important;
max-width:980px!important;
margin:0 auto!important;
color:#ece4d4!important;
-webkit-text-fill-color:#ece4d4!important;
font-family:"Noto Sans SC","Source Han Sans SC","Microsoft YaHei",sans-serif!important;
font-size:15px!important;
line-height:1.7!important;
letter-spacing:.012em!important;
}
.cw-runtime,
.cw-runtime div,
.cw-runtime section,
.cw-runtime article,
.cw-runtime details,
.cw-runtime summary,
.cw-runtime header,
.cw-runtime dl,
.cw-runtime table{
box-sizing:border-box!important;
}
.cw-runtime a{
color:#e0bd73!important;
-webkit-text-fill-color:#e0bd73!important;
text-decoration:none!important;
}
.cw-runtime a:hover{
text-decoration:underline!important;
text-decoration-color:rgba(224,189,115,.6)!important;
}
.cw-runtime h2,
.cw-runtime h3,
.cw-runtime h4,
.cw-runtime h5{
font-family:"Noto Serif SC","Source Han Serif SC","Songti SC","STSong",serif!important;
}

/* ===== §B 山河行卷 ===== */
.cw-story{
position:relative!important;
margin:15px 0!important;
border:1px solid rgba(207,171,96,.28)!important;
border-radius:14px!important;
background:#111720!important;
box-shadow:0 14px 34px rgba(0,0,0,.28)!important;
overflow:hidden!important;
}
.cw-story::before{
content:""!important;
position:absolute!important;
left:0!important;
top:0!important;
right:0!important;
height:2px!important;
background:linear-gradient(90deg,transparent,#d2ad62,transparent)!important;
opacity:.84!important;
}
.cw-story-head{
padding:22px 23px 18px!important;
border-bottom:1px solid rgba(207,171,96,.18)!important;
background:radial-gradient(circle at 15% 0,rgba(210,173,98,.13),transparent 46%),#151b24!important;
}
.cw-kicker{
display:inline-block!important;
margin:0 0 7px!important;
color:#d9b86e!important;
-webkit-text-fill-color:#d9b86e!important;
font-size:.78rem!important;
font-weight:700!important;
letter-spacing:.14em!important;
}
.cw-story-head h2{
margin:0!important;
color:#f4ead6!important;
-webkit-text-fill-color:#f4ead6!important;
font-size:1.52rem!important;
line-height:1.38!important;
letter-spacing:.045em!important;
}
.cw-story-head p{
margin:8px 0 0!important;
color:#a99f8d!important;
-webkit-text-fill-color:#a99f8d!important;
font-size:.9rem!important;
line-height:1.6!important;
}
.cw-prose{
padding:21px 23px 23px!important;
font-family:"Noto Serif SC","Source Han Serif SC","Songti SC","STSong",serif!important;
font-size:1rem!important;
line-height:1.9!important;
color:#e9e0cf!important;
-webkit-text-fill-color:#e9e0cf!important;
}
.cw-prose p{
margin:0 0 1.12em!important;
text-align:justify!important;
text-indent:2em!important;
word-break:break-word!important;
color:#e9e0cf!important;
-webkit-text-fill-color:#e9e0cf!important;
}
.cw-prose p:last-child{
margin-bottom:0!important;
}
.cw-prose blockquote{
margin:1em 0!important;
padding:10px 15px!important;
border-left:3px solid #8d703a!important;
background:#181d22!important;
color:#d8cebc!important;
-webkit-text-fill-color:#d8cebc!important;
}
.cw-check-card{
margin:0 18px 18px!important;
padding:14px!important;
border:1px solid rgba(185,94,90,.34)!important;
border-radius:11px!important;
background:linear-gradient(135deg,rgba(185,94,90,.1),#10151d)!important;
}
.cw-check-card h3{
margin:0 0 10px!important;
color:#e1aaa6!important;
-webkit-text-fill-color:#e1aaa6!important;
font-size:1rem!important;
}
.cw-check-grid{
display:grid!important;
grid-template-columns:repeat(2,minmax(0,1fr))!important;
gap:8px!important;
}
.cw-check-grid>div{
display:flex!important;
flex-direction:column!important;
gap:4px!important;
padding:9px 10px!important;
border:1px solid rgba(185,94,90,.18)!important;
border-radius:8px!important;
background:#14181f!important;
}
.cw-check-grid b{
color:#dba7a3!important;
-webkit-text-fill-color:#dba7a3!important;
font-size:.8rem!important;
}
.cw-check-grid span,
.cw-check-card>p{
color:#d5cbbb!important;
-webkit-text-fill-color:#d5cbbb!important;
}
.cw-check-card>p{
margin:10px 0 0!important;
}

/* ===== §C 通用折叠面板 ===== */
.cw-panel{
position:relative!important;
display:block!important;
width:100%!important;
margin:14px 0!important;
border:1px solid var(--cw-line)!important;
border-radius:14px!important;
background:#111720!important;
box-shadow:0 12px 30px rgba(0,0,0,.25)!important;
overflow:hidden!important;
}
.cw-panel::before{
content:""!important;
position:absolute!important;
left:0!important;
top:0!important;
right:0!important;
height:2px!important;
background:linear-gradient(90deg,transparent,var(--cw-gold),transparent)!important;
opacity:.8!important;
}
.cw-panel>summary{
list-style:none!important;
cursor:pointer!important;
min-height:56px!important;
display:flex!important;
align-items:center!important;
gap:10px!important;
padding:13px 48px 13px 16px!important;
background:linear-gradient(90deg,rgba(210,173,98,.1),rgba(18,24,33,.96) 68%)!important;
color:#f0e6d2!important;
-webkit-text-fill-color:#f0e6d2!important;
font-weight:700!important;
position:relative!important;
user-select:none!important;
transition:background .18s ease,border-color .18s ease!important;
}
.cw-panel>summary::-webkit-details-marker{
display:none!important;
}
.cw-panel>summary::after{
content:"⌄"!important;
position:absolute!important;
right:17px!important;
top:50%!important;
transform:translateY(-50%) rotate(-90deg)!important;
color:var(--cw-gold)!important;
-webkit-text-fill-color:var(--cw-gold)!important;
font-size:20px!important;
line-height:1!important;
transition:transform .18s ease!important;
}
.cw-panel[open]>summary::after{
transform:translateY(-50%) rotate(0deg)!important;
}
.cw-panel>summary:hover{
background:linear-gradient(90deg,rgba(210,173,98,.14),#18202b 72%)!important;
}
.cw-panel[open]>summary{
border-bottom:1px solid rgba(207,171,96,.15)!important;
}
.cw-panel>summary:focus-visible{
outline:2px solid #d2ad62!important;
outline-offset:-3px!important;
}
.cw-panel>summary>span:not(.cw-summary-icon){
color:#f0e6d2!important;
-webkit-text-fill-color:#f0e6d2!important;
}
.cw-panel>summary small{
margin-left:auto!important;
color:#9c927f!important;
-webkit-text-fill-color:#9c927f!important;
font-size:.76rem!important;
font-weight:500!important;
letter-spacing:.045em!important;
white-space:nowrap!important;
}
.cw-summary-icon{
width:30px!important;
height:30px!important;
flex:0 0 30px!important;
display:inline-flex!important;
align-items:center!important;
justify-content:center!important;
border:1px solid var(--cw-line)!important;
border-radius:50%!important;
background:rgba(210,173,98,.09)!important;
color:var(--cw-gold)!important;
-webkit-text-fill-color:var(--cw-gold)!important;
font-size:14px!important;
box-shadow:inset 0 0 0 3px rgba(210,173,98,.035)!important;
transition:transform .18s ease,background .18s ease!important;
}
.cw-panel[open]>summary .cw-summary-icon{
transform:scale(1.04)!important;
background:rgba(210,173,98,.13)!important;
}
.cw-panel-body{
padding:16px!important;
background:#0f151d!important;
color:#e7decd!important;
-webkit-text-fill-color:#e7decd!important;
}
.cw-panel[open]>.cw-panel-body{
animation:cwPanelReveal .18s ease both!important;
}
@keyframes cwPanelReveal{
from{opacity:0;transform:translateY(-4px);}
to{opacity:1;transform:translateY(0);}
}

.cw-panel::details-content{
block-size:0!important;
opacity:0!important;
overflow:clip!important;
transition:block-size .18s ease,opacity .18s ease!important;
}
.cw-panel[open]::details-content{
block-size:auto!important;
opacity:1!important;
}


/* ===== §D 玄枢推演 ===== */
.cw-thought{
--cw-line:rgba(145,123,177,.38)!important;
--cw-gold:#bda9da!important;
}
.cw-thought::before{
background:linear-gradient(90deg,transparent,#917bb1,transparent)!important;
}
.cw-thought>summary{
background:linear-gradient(90deg,rgba(145,123,177,.13),#151923 72%)!important;
}
.cw-thought .cw-summary-icon{
color:#c7b6df!important;
-webkit-text-fill-color:#c7b6df!important;
border-color:rgba(145,123,177,.42)!important;
background:rgba(145,123,177,.1)!important;
}
.cw-thought-grid{
display:grid!important;
grid-template-columns:repeat(2,minmax(0,1fr))!important;
gap:10px!important;
}
.cw-thought-item{
display:flex!important;
flex-direction:column!important;
gap:4px!important;
padding:11px 12px!important;
border:1px solid rgba(145,123,177,.22)!important;
border-radius:10px!important;
background:#151825!important;
}
.cw-thought-item b{
color:#cdbce4!important;
-webkit-text-fill-color:#cdbce4!important;
font-size:.82rem!important;
letter-spacing:.07em!important;
}
.cw-thought-item span{
color:#c8c0b3!important;
-webkit-text-fill-color:#c8c0b3!important;
font-size:.9rem!important;
line-height:1.65!important;
}

/* ===== §E 命主玉牒与资料行 ===== */
.cw-player{
--cw-line:rgba(210,173,98,.35)!important;
--cw-gold:#d2ad62!important;
}
.cw-dl{
margin:0!important;
display:grid!important;
grid-template-columns:repeat(2,minmax(0,1fr))!important;
gap:9px 10px!important;
font-family:"Noto Sans SC","Source Han Sans SC","Microsoft YaHei",sans-serif!important;
}
.cw-row{
display:grid!important;
grid-template-columns:minmax(92px,.38fr) minmax(0,1fr)!important;
min-width:0!important;
border:1px solid rgba(207,171,96,.17)!important;
border-radius:9px!important;
background:#111720!important;
overflow:hidden!important;
}
.cw-row:nth-child(even){
background:#131a24!important;
}
.cw-row dt{
margin:0!important;
padding:10px 11px!important;
background:#171d25!important;
color:#d6b76d!important;
-webkit-text-fill-color:#d6b76d!important;
font-family:"Noto Serif SC","Source Han Serif SC","Songti SC",serif!important;
font-size:.84rem!important;
font-weight:700!important;
font-style:italic!important;
line-height:1.55!important;
}
.cw-row dd{
margin:0!important;
padding:10px 12px!important;
color:#e6ddcc!important;
-webkit-text-fill-color:#e6ddcc!important;
font-size:.92rem!important;
line-height:1.75!important;
word-break:break-word!important;
}

/* ===== §F 语义子版块 ===== */
.cw-section{
position:relative!important;
margin:0 0 14px!important;
padding:16px!important;
border:1px solid rgba(207,171,96,.18)!important;
border-left-width:3px!important;
border-radius:12px!important;
background:#141a23!important;
box-shadow:0 4px 12px rgba(0,0,0,.12)!important;
}
.cw-section:last-child{
margin-bottom:0!important;
}
.cw-section h3,
.cw-section h4,
.cw-section h5{
margin:0 0 12px!important;
color:#eee4d1!important;
-webkit-text-fill-color:#eee4d1!important;
line-height:1.45!important;
}
.cw-section h3{
font-size:1.08rem!important;
}
.cw-section h4{
font-size:1rem!important;
}
.cw-section h5{
font-size:.94rem!important;
}
.cw-sec-profile{
border-left-color:#6c99b8!important;
background:linear-gradient(135deg,rgba(108,153,184,.08),#141a23 44%)!important;
}
.cw-sec-realm{
border-left-color:#d2ad62!important;
background:linear-gradient(135deg,rgba(210,173,98,.08),#161a20 44%)!important;
}
.cw-sec-skill{
border-left-color:#7c91a7!important;
background:linear-gradient(135deg,rgba(124,145,167,.09),#131a22 46%)!important;
}
.cw-sec-ability{
border-left-color:#917bb1!important;
background:linear-gradient(135deg,rgba(145,123,177,.09),#151823 46%)!important;
}
.cw-sec-relation{
border-left-color:#b95e5a!important;
background:linear-gradient(135deg,rgba(185,94,90,.075),#17191f 48%)!important;
}
.cw-sec-romance{
border-left-color:#9b4f58!important;
background:linear-gradient(135deg,rgba(155,79,88,.08),#18171d 48%)!important;
}
.cw-sec-inventory{
border-left-color:#5f9d9c!important;
background:linear-gradient(135deg,rgba(95,157,156,.075),#131b20 48%)!important;
}
.cw-sec-assets{
border-left-color:#aa7448!important;
background:linear-gradient(135deg,rgba(170,116,72,.09),#191814 48%)!important;
}
.cw-sec-affairs{
border-left-color:#b88750!important;
background:linear-gradient(135deg,rgba(184,135,80,.09),#191a18 48%)!important;
}
.cw-sec-news{
border-left-color:#6f9f7b!important;
}
.cw-sec-compass{
border-left-color:#6c99b8!important;
}
.cw-sec-actions{
border-left-color:#d2ad62!important;
}
.cw-mem-near{
