/* ===== §G 武藏真传、天赋神通与卡片 ===== */
.cw-card-list{
display:grid!important;
grid-template-columns:repeat(2,minmax(0,1fr))!important;
gap:10px!important;
}
.cw-skill-card,
.cw-ability-card{
min-width:0!important;
padding:13px 14px!important;
border:1px solid rgba(108,153,184,.28)!important;
